const invoiceDocWithoutQr=iDoc;
iDoc=function(i){let html=invoiceDocWithoutQr(i);if(i.language==='en')html=html.replace('<th class="num">DPH</th>','<th class="num">VAT</th>');else html=html.replace('Company ID:','IČO:').replace('Tax ID:','DIČ:').replace('VAT ID:','IČ DPH:');const message=iQrEligible(i)?'Preparing payment QR…':iQrValidationError(i);const qr='<div class="invoice-doc-qr"><div class="invoice-qr-placeholder">'+message+'</div><small>PAY by square · Scan to pay</small></div>';return html.replace('</div></div><div class="invoice-doc-footer">','</div>'+qr+'</div><div class="invoice-doc-footer">')};
const invoicePreviewWithoutQr=invoicePreview;
invoicePreview=function(id){invoicePreviewWithoutQr(id);const i=db.invoices.find(x=>x.id===id);if(i)iAttachQr(i,document.getElementById('modal'))};
invoiceDownloadPdf=async function(id){const i=db.invoices.find(x=>x.id===id);if(!i)return;try{const result=await iPdf(i),name=(i.number||'invoice').replace(/[^\p{L}\p{N}._-]+/gu,'_')+'.pdf';download(name,result.blob,'application/pdf');toast(result.hasQr?'PDF downloaded with PAY by square QR.':'PDF downloaded. '+(result.qrError||'Payment QR is unavailable.'))}catch(e){console.error(e);toast('Could not create the PDF')}};

function iNormalizedIban(value){return String(value||'').replace(/[\s-]+/g,'').toUpperCase()}
function iValidIban(value){const iban=iNormalizedIban(value);if(globalThis.VeltoPaymentQr?.isIBAN)return globalThis.VeltoPaymentQr.isIBAN(iban);if(!/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(iban))return false;const required={SK:24,CZ:24,AT:20,DE:22,FR:27,GB:22,NL:18,PL:28,HU:28,IT:27,ES:24,BE:16,CH:21};if(required[iban.slice(0,2)]&&iban.length!==required[iban.slice(0,2)])return false;let remainder=0;for(const ch of iban.slice(4)+iban.slice(0,4)){const value=ch.charCodeAt(0);remainder=value>=65?(remainder*100+value-55)%97:(remainder*10+value-48)%97}return remainder===1}
function iQrValidationError(i){const english=i?.language==='en';if(!String(i?.supplierName||'').trim())return english?'Enter the supplier name to include a payment QR.':'Pre platobný QR kód zadajte názov dodávateľa.';if(!iValidIban(i?.iban))return english?'Enter a valid IBAN to include a payment QR.':'Pre platobný QR kód zadajte platný IBAN.';const total=iTotals(i).total;if(!Number.isFinite(total)||total<=0)return english?'The invoice total must be positive for a payment QR.':'Pre platobný QR kód musí byť suma faktúry kladná.';const bic=String(i.swift||'').replace(/\s+/g,'').toUpperCase();if(bic&&!/^[A-Z]{6}[A-Z0-9]{2}(?:[A-Z0-9]{3})?$/.test(bic))return english?'Enter a valid SWIFT/BIC or leave it blank.':'Zadajte platný SWIFT/BIC alebo ho ponechajte prázdny.';const vs=String(i.variableSymbol||'').trim(),cs=String(i.constantSymbol||'').trim();if(vs&&!/^\d{1,10}$/.test(vs))return english?'The variable symbol must contain 1 to 10 digits.':'Variabilný symbol musí obsahovať 1 až 10 číslic.';if(cs&&!/^\d{1,4}$/.test(cs))return english?'The constant symbol must contain 1 to 4 digits.':'Konštantný symbol musí obsahovať 1 až 4 číslice.';return ''}
function iQrEligible(i){return !iQrValidationError(i)}
function iQrData(i){const invalid=iQrValidationError(i);if(invalid)throw new Error(invalid);const api=globalThis.VeltoPaymentQr;if(!api)throw new Error('The local payment QR module did not load. Reload Velto and try again.');const account={iban:iNormalizedIban(i.iban)},bic=String(i.swift||'').replace(/\s+/g,'').toUpperCase();if(bic)account.bic=bic;const payment={type:api.PaymentOptions.PaymentOrder,amount:iTotals(i).total,currencyCode:api.CurrencyCode.EUR,beneficiary:{name:String(i.supplierName).trim().slice(0,70)},bankAccounts:[account],paymentNote:('Invoice '+String(i.number||'')).slice(0,140)};if(i.dueDate)payment.paymentDueDate=String(i.dueDate).replace(/-/g,'');const vs=String(i.variableSymbol||'').trim()||String(i.number||'').replace(/\D/g,'');if(/^\d{1,10}$/.test(vs))payment.variableSymbol=vs;const cs=String(i.constantSymbol||'').trim();if(cs)payment.constantSymbol=cs;const model={payments:[payment]},payload=api.encode(model),matrix=api.matrix(payload,{mode:'alphanumeric',ecclevel:'L'});return{payload,matrix,margin:4,model}}
async function iQrPayload(i){const data=iQrData(i),ns='http://www.w3.org/2000/svg',total=data.matrix.length+data.margin*2,svg=document.createElementNS(ns,'svg');for(const [name,value] of Object.entries({viewBox:'0 0 '+total+' '+total,width:'512',height:'512',role:'img','aria-label':'PAY by square payment QR code','shape-rendering':'crispEdges'}))svg.setAttribute(name,value);const background=document.createElementNS(ns,'rect');background.setAttribute('width',String(total));background.setAttribute('height',String(total));background.setAttribute('fill','#fff');svg.append(background);const path=document.createElementNS(ns,'path');let commands='';data.matrix.forEach((row,r)=>{let c=0;while(c<row.length){if(!row[c]){c++;continue}const start=c;while(c<row.length&&row[c])c++;commands+='M'+(start+data.margin)+' '+(r+data.margin)+'h'+(c-start)+'v1h-'+(c-start)+'z'}});path.setAttribute('d',commands);path.setAttribute('fill','#000');svg.append(path);return svg}
async function iQrImage(i){const data=iQrData(i),scale=8,total=data.matrix.length+data.margin*2,canvas=document.createElement('canvas');canvas.width=canvas.height=total*scale;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#000';data.matrix.forEach((row,r)=>row.forEach((dark,c)=>{if(dark)ctx.fillRect((c+data.margin)*scale,(r+data.margin)*scale,scale,scale)}));return{img:canvas,matrix:data.matrix,margin:data.margin,payload:data.payload,url:null}}
async function iAttachQr(i,root=document){const box=root.querySelector('.invoice-doc-qr');if(!box)return null;const placeholder=box.querySelector('.invoice-qr-placeholder');if(!iQrEligible(i)){if(placeholder)placeholder.textContent=iQrValidationError(i);return null}try{const svg=await iQrPayload(i);svg.setAttribute('class','invoice-qr-svg');if(placeholder)placeholder.remove();box.prepend(svg);box.classList.add('ready');return svg}catch(e){console.error('Payment QR could not be generated:',e);if(placeholder)placeholder.textContent=e.message||'Payment QR could not be generated.';return null}}



// Local folder access is granted by the user's folder/file picker, never by a Dropbox token.
let iLocalDropboxFolder=null,iLocalDropboxSaveBusy=false;
function iDropboxFolderStore(handle,write=false){return new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(new Error('Folder preferences cannot be stored in this browser'));let request;try{request=indexedDB.open('VeltoInvoiceFolders',1)}catch(error){reject(error);return}request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains('folders'))request.result.createObjectStore('folders')};request.onerror=()=>reject(request.error||new Error('Folder preferences could not be opened'));request.onblocked=()=>reject(new Error('Folder preferences are busy in another tab'));request.onsuccess=()=>{const database=request.result;let result=null;try{const transaction=database.transaction('folders',write?'readwrite':'readonly'),store=transaction.objectStore('folders'),operation=write?(handle?store.put(handle,'dropbox'):store.delete('dropbox')):store.get('dropbox');operation.onsuccess=()=>{if(!write)result=operation.result||null};transaction.oncomplete=()=>{database.close();resolve(result)};transaction.onerror=transaction.onabort=()=>{database.close();reject(transaction.error||new Error('Folder preferences could not be saved'))}}catch(error){database.close();reject(error)}}})}
function iLocalInvoicePdfName(invoice){let name=String(invoice.number||'invoice').replace(/[^\p{L}\p{N}._-]+/gu,'_').replace(/^\.+|[. ]+$/g,'').slice(0,120)||'invoice';if(/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(name))name='invoice_'+name;return name+'.pdf'}
function iIsLocalDropboxLocation(folder){return folder?.kind==='directory'&&typeof folder.getFileHandle==='function'&&/^(dropbox|invoice)$/i.test(String(folder.name||''))}
async function iDropboxInvoiceDirectory(folder){if(!iIsLocalDropboxLocation(folder))throw new Error('Choose your Dropbox folder or the Invoice folder inside Dropbox.');if(/^invoice$/i.test(folder.name))return folder;try{return await folder.getDirectoryHandle('Invoice',{create:true})}catch(error){if(error.name==='TypeMismatchError')throw new Error('Dropbox contains a file named Invoice. Rename that file or select an Invoice folder.');throw error}}
async function iChooseLocalDropboxFolder(){if(typeof window.showDirectoryPicker!=='function')throw new Error('To choose a local Dropbox folder, open Velto in Microsoft Edge or Chrome.');const folder=await window.showDirectoryPicker({id:'velto-dropbox-invoices',mode:'readwrite',startIn:iLocalDropboxFolder||'documents'});if(!iIsLocalDropboxLocation(folder))throw new Error('Choose your Dropbox folder or the Invoice folder inside Dropbox.');iLocalDropboxFolder=folder;await iDropboxFolderStore(folder,true).catch(error=>console.warn('Velto will remember this folder for this tab only:',error));return folder}
async function invoiceChooseLocalDropboxFolder(){if(typeof window.showDirectoryPicker!=='function'&&typeof window.showSaveFilePicker==='function')return toast('Click Dropbox beside an invoice, then select Dropbox/Invoice in Save As.');try{const folder=await iChooseLocalDropboxFolder();toast('Invoice PDF destination: Dropbox/Invoice');if(page==='invoices')render()}catch(error){if(error.name==='AbortError')return;console.error(error);toast(error.message||'Could not select the Dropbox folder')}}
async function iGetLocalDropboxDestination(name){if(typeof window.showDirectoryPicker==='function'){let folder=iLocalDropboxFolder;if(folder&&!iIsLocalDropboxLocation(folder)){iLocalDropboxFolder=null;folder=null}if(folder){let permission=typeof folder.queryPermission==='function'?await folder.queryPermission({mode:'readwrite'}):'granted';if(permission!=='granted'&&typeof folder.requestPermission==='function')permission=await folder.requestPermission({mode:'readwrite'});if(permission!=='granted'){iLocalDropboxFolder=null;await iDropboxFolderStore(null,true).catch(()=>{});throw new Error('Folder access was not granted. Click Dropbox again to choose your local folder.')}}else folder=await iChooseLocalDropboxFolder();const invoiceFolder=await iDropboxInvoiceDirectory(folder);return{folder:invoiceFolder,folderName:'Dropbox/Invoice'}}if(typeof window.showSaveFilePicker==='function'){toast('Select the Invoice folder inside Dropbox in Save As.');const file=await window.showSaveFilePicker({id:'velto-dropbox-invoices',suggestedName:name,startIn:'documents',types:[{description:'PDF invoice',accept:{'application/pdf':['.pdf']}}]});return{file,folderName:'your selected local Invoice folder'}}throw new Error('This browser cannot save directly to a folder. Open Velto in Microsoft Edge or Chrome, then click Dropbox and choose Dropbox/Invoice.')}
async function invoiceSaveToLocalDropbox(id){const invoice=db.invoices.find(item=>item.id===id);if(!invoice)return;if(iLocalDropboxSaveBusy)return toast('An invoice PDF is already being saved');iLocalDropboxSaveBusy=true;let writer=null;try{const suggestedName=iLocalInvoicePdfName(invoice);const destination=await iGetLocalDropboxDestination(suggestedName);const result=await iPdf(invoice),blob=result instanceof Blob?result:result.blob;if(!(blob instanceof Blob))throw new Error('The invoice PDF could not be created');const file=destination.file||await destination.folder.getFileHandle(suggestedName,{create:true});writer=await file.createWritable();await writer.write(blob);await writer.close();writer=null;invoice.localDropboxFileName=file.name||suggestedName;invoice.localDropboxFolderName=destination.folderName;invoice.localDropboxSavedAt=new Date().toISOString();save();if(page==='invoices')render();toast('PDF saved to '+destination.folderName+': '+invoice.localDropboxFileName+(!result.hasQr&&result.qrError?' ('+result.qrError+')':''))}catch(error){if(writer&&typeof writer.abort==='function')await writer.abort().catch(()=>{});if(error.name==='AbortError')return;console.error('Local Dropbox save failed:',error);if(error.name==='NotFoundError'){iLocalDropboxFolder=null;await iDropboxFolderStore(null,true).catch(()=>{});toast('That folder is no longer available. Click Dropbox again to select it.')}else toast(error.message||'Could not save the PDF to your local Dropbox folder')}finally{iLocalDropboxSaveBusy=false}}
iDropboxFolderStore().then(folder=>{if(!iLocalDropboxFolder)iLocalDropboxFolder=folder}).catch(()=>{});
